package com.nextfeet.nextfeet.service; import java.util.*; import org.springframework.stereotype.Service; import com.nextfeet.nextfeet.model.Zapatilla; import com.nextfeet.nextfeet.repository.ZapatillaDAO; @Service public class ZapatillaServiceImpl implements ZapatillaService {private final ZapatillaDAO dao; public ZapatillaServiceImpl(ZapatillaDAO dao){this.dao=dao;} public List<Zapatilla> catalogo(String q,String m,Integer c,Double a,Double b){return dao.catalogo(q,m,c,a,b);} public List<Zapatilla> listar(){return dao.listar();} public Zapatilla obtener(Integer id){return dao.obtener(id);} public void crear(Zapatilla z){dao.crear(z);} public void actualizar(Zapatilla z){dao.actualizar(z);} public void desactivar(Integer id){dao.cambiarEstado(id,"INACTIVO");} public void eliminar(Integer id){dao.eliminar(id);} public int stock(Integer id,String t){return dao.stock(id,t);} public void ajustarStock(Integer id,String t,int d){dao.ajustarStock(id,t,d);}}